import { useState, createContext, useContext, useMemo, useReducer } from 'react';

// Compound Components Pattern
const SelectContext = createContext(null);

function Select({ children, value, onChange }) {
  const contextValue = useMemo(() => ({ value, onChange }), [value, onChange]);

  return (
    <SelectContext.Provider value={contextValue}>
      <div className="select">{children}</div>
    </SelectContext.Provider>
  );
}

function Option({ value, children }) {
  const { value: selectedValue, onChange } = useContext(SelectContext);
  const isSelected = value === selectedValue;

  return (
    <div className={`option ${isSelected ? 'selected' : ''}`} onClick={() => onChange(value)}>
      {children}
    </div>
  );
}

// Render Props Pattern
function MouseTracker({ render }) {
  const [position, setPosition] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e) => {
    setPosition({ x: e.clientX, y: e.clientY });
  };

  return (
    <div onMouseMove={handleMouseMove}>
      {render(position)}
    </div>
  );
}

// Higher-Order Component Pattern
function withLoading(WrappedComponent) {
  return function WithLoadingComponent({ isLoading, ...props }) {
    if (isLoading) {
      return <div className="spinner">Loading...</div>;
    }
    return <WrappedComponent {...props} />;
  };
}

// State Reducer Pattern
const toggleReducer = (state, action) => {
  switch (action.type) {
    case 'TOGGLE': return { ...state, isOn: !state.isOn };
    case 'SET': return { ...state, isOn: action.payload };
    case 'RESET': return { ...state, isOn: state.initialState };
    default: return state;
  }
};

function useToggle(initialState = false) {
  const [state, dispatch] = useReducer(toggleReducer, {
    isOn: initialState,
    initialState
  });

  return {
    isOn: state.isOn,
    toggle: () => dispatch({ type: 'TOGGLE' }),
    set: (value) => dispatch({ type: 'SET', payload: value }),
    reset: () => dispatch({ type: 'RESET' })
  };
}

// Control Props Pattern
function ControlledInput({ value, onChange, defaultValue }) {
  const isControlled = value !== undefined;
  const [internalValue, setInternalValue] = useState(defaultValue || '');

  const currentValue = isControlled ? value : internalValue;

  const handleChange = (e) => {
    const newValue = e.target.value;
    if (!isControlled) setInternalValue(newValue);
    onChange?.(e);
  };

  return <input value={currentValue} onChange={handleChange} />;
}
